// Retire the service worker previously generated by vite-plugin-pwa.
//
// Keep this file at /sw.js so existing installations can update to it. A
// service worker without a fetch handler does not intercept or cache requests.
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    // Take control from the old Workbox worker immediately.
    await self.clients.claim();

    // Only Cache Storage is cleared. localStorage and IndexedDB (including
    // authentication and localforage data) are left intact.
    const cacheNames = await caches.keys();
    await Promise.all(cacheNames.map((cacheName) => caches.delete(cacheName)));

    // Reload open Connect windows once so they are fetched from the network.
    const windowClients = await self.clients.matchAll({ type: 'window' });
    await Promise.all(windowClients.map((client) => (
      client.navigate(client.url).catch(() => undefined)
    )));
  })());
});

// Intentionally no fetch handler: all requests go directly to the network.
